package corpagent.api;

import static corpagent.api.RealFunctionalTest.*;
import corpagent.*;
import corpagent.data.*;
import corpagent.db.*;
import corpagent.files.*;
import corpagent.tools.*;
import corpagent.util.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.ZipFile;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

/** Opt-in real-provider coverage of every shipped skill/tool/template and reference routing. */
public final class ScenarioMatrixTest {
    static final String IT="Методология ИТ проектов",PM="Методология LPG";
    static String project,projectPath;
    static String skill(String part){return store.getSkills().keySet().stream().filter(x->x.toLowerCase().contains(part)).findFirst().orElseThrow();}
    static Map<String,Object> ctx(String selectedSkill,String selectedTool){Map<String,Object> c=obj("databases",List.of(project));if(selectedSkill!=null)c.put("skills",List.of(selectedSkill));if(selectedTool!=null)c.put("tools",List.of(selectedTool));return c;}
    static String scalarText(String path,String sql)throws Exception{try(var c=SqliteHelper.open(path);var s=c.createStatement();var rows=s.executeQuery(sql)){return rows.next()?rows.getString(1):"";}}
    static void sql(String path,String query){var r=SqliteHelper.executeQuery(path,query);check(r.success,"Fixture SQL failed: "+r.error);}
    static void pptTheme(Path generated,String template)throws Exception{try(var a=new ZipFile(generated.toFile());var b=new ZipFile(template)){String entry="ppt/theme/theme1.xml";check(xmlSignature(a.getInputStream(a.getEntry(entry)).readAllBytes()).equals(xmlSignature(b.getInputStream(b.getEntry(entry)).readAllBytes())),"wrong PPT theme selected");}verifyDownload(generated);}
    static void excelTemplate(Path generated,String template)throws Exception{try(var a=new XSSFWorkbook(Files.newInputStream(generated));var b=new XSSFWorkbook(Files.newInputStream(Paths.get(template)))){check(a.getNumCellStyles()>=b.getNumCellStyles(),"Excel styles lost");check(a.getSheetAt(0).getRow(1).toString().equals(b.getSheetAt(0).getRow(1).toString()),"Excel static header changed");}verifyDownload(generated);}
    public static void runMatrix(Agent agent,FileCreator creator,DatabaseManager manager)throws Exception{
        run("inventory_7_skills_4_tools",()->{check(store.getSkills().size()==7&&store.getTools().size()==4,"preset inventory changed");});
        run("empty_it_methodology_no_fabrication",()->{long before=TokenBudget.tokensToday();String text=response(chat("empty-it","Ответь по методологии ИТ: какие обязательные этапы?",null));check(text.contains(IT)&&text.contains("нет материалов")&&TokenBudget.tokensToday()==before,"empty IT source was replaced by model knowledge");});
        run("empty_lpg_methodology_no_fabrication",()->{long before=TokenBudget.tokensToday();String text=response(chat("empty-lpg","Что требует методология проектного управления LPG?",null));check(text.contains(PM)&&text.contains("нет материалов")&&TokenBudget.tokensToday()==before,"empty LPG source was replaced by model knowledge");});
        String itPath=Json.str(store.getDatabase(IT),"path","");String pmPath=Json.str(store.getDatabase(PM),"path","");
        for(int i=1;i<=9;i++){sql(itPath,"INSERT INTO frameworks(name,type,description) VALUES ('SYNTHETIC_IT_"+i+"','synthetic','"+(i==9?"SYNTHETIC_IT_BOUNDARY: IT_FOLLOW_8147":"Synthetic example "+i)+"')");sql(pmPath,"INSERT INTO rules(category,rule,description) VALUES ('synthetic','"+(i==9?"SYNTHETIC_LPG_BOUNDARY: LPG_FOLLOW_9263":"Synthetic rule "+i)+"','Synthetic only')");}
        Map<String,Object> created=api("POST","/api/projects",obj("name","MATRIX_PROJECT_ALPHA","db_name","matrix_project","description","Synthetic scenario matrix"));project=Json.str(created,"db","");projectPath=Json.str(store.getDatabase(project),"path","");
        sql(projectPath,"INSERT INTO risks(project_id,title,priority,probability,impact,status,mitigation) VALUES(1,'MATRIX_RISK_DELAY','high','high','high','open','Prepare fallback')");
        sql(projectPath,"INSERT INTO tasks(project_id,title,assignee,status,priority,due_date) VALUES(1,'MATRIX_TASK_OPEN','Test Owner','open','high','2026-11-20')");
        sql(projectPath,"INSERT INTO tasks(project_id,title,assignee,status,priority,due_date) VALUES(1,'MATRIX_TASK_DONE','Test Owner','done','medium','2026-11-01')");
        run("it_source_auto_selection_row_beyond_preview",()->{Map<String,Object> r=chat("method-it","По методологии IT найди SYNTHETIC_IT_BOUNDARY в frameworks и сообщи предписанное значение. Не используй общие знания.",null);check(response(r).contains("IT_FOLLOW_8147")&&Json.arr(r,"usage").toString().contains(IT),"IT answer did not read required source");});
        run("pm_source_auto_selection_row_beyond_preview",()->{Map<String,Object> r=chat("method-pm","По методологии проектного управления LPG найди SYNTHETIC_LPG_BOUNDARY в rules и сообщи предписанное значение.",null);check(response(r).contains("LPG_FOLLOW_9263")&&Json.arr(r,"usage").toString().contains(PM),"LPG answer did not read required source");});
        run("both_methodologies_with_project_db_selected",()->{Map<String,Object> r=chat("method-both","Сравни контрольные предписания методологий IT и LPG: SYNTHETIC_IT_BOUNDARY из frameworks и SYNTHETIC_LPG_BOUNDARY из rules. Прочитай обе базы.",obj("databases",List.of(project,PM)));check(response(r).contains("IT_FOLLOW_8147")&&response(r).contains("LPG_FOLLOW_9263"),"one reference source ignored");check(Json.arr(r,"usage").toString().contains(IT)&&Json.arr(r,"usage").toString().contains(PM),"source attribution incorrect");});
        run("reference_write_denied_even_when_confirmed",()->{String before=scalarText(pmPath,"SELECT rule FROM rules WHERE id=9");chat("method-write","По методологии LPG измени в БД поле rule записи rules id=9 на CHANGED через db_execute. Запись подтверждена.",obj("confirm_writes",true));check(before.equals(scalarText(pmPath,"SELECT rule FROM rules WHERE id=9")),"reference database was writable");});
        run("named_database_scope_and_write_guard",()->{ToolExecutor executor=new ToolExecutor(store,new ToolRegistry(store));executor.setActiveDatabase(projectPath,project);executor.setQueryDatabases(List.of(project,IT,PM));String good=executor.executeBuiltinSql("db_query",obj("database",IT,"sql","SELECT description FROM frameworks WHERE id=9"));check(good.contains("IT_FOLLOW_8147"),"named source routing failed");check(executor.executeBuiltinSql("db_query",obj("database","outside-chat","sql","SELECT 1")).contains("не выбрана"),"unselected database accessible");check(!executor.executeBuiltinSql("db_execute",obj("database",PM,"sql","UPDATE rules SET rule='bad' WHERE id=9")).contains("Затронуто строк"),"named reference write succeeded");});
        run("skill_passport_incomplete_fields",()->{String text=response(chat("skill-passport","Проверь полноту паспорта выбранного проекта по БД. Что нужно дополнить?",ctx(skill("паспорт"),null)));check(text.contains("MATRIX_PROJECT_ALPHA")&&(text.toLowerCase().contains("smart")||text.toLowerCase().contains("цели"))&&text.toLowerCase().contains("команд"),"passport skill omitted required checks");});
        run("skill_risks_two_mitigations",()->{String text=response(chat("skill-risks","Проанализируй риск MATRIX_RISK_DELAY из БД: вероятность, влияние, приоритет. Две меры снижения оформи разделами MITIGATION_1 и MITIGATION_2.",ctx(skill("рискам"),null)));check(text.contains("MATRIX_RISK_DELAY")&&text.contains("MITIGATION_1")&&text.contains("MITIGATION_2"),"risk skill did not provide two mitigations");});
        run("skill_plan_reads_actual_statuses",()->{String text=response(chat("skill-plan","Покажи текущий план из tasks с ответственными, сроками и статусами open/done. Не добавляй выдуманные задачи.",ctx(skill("планом"),null)));check(text.contains("MATRIX_TASK_OPEN")&&text.contains("MATRIX_TASK_DONE")&&text.contains("open")&&text.contains("done"),"plan skill ignored actual tasks");});
        run("skill_meetings_two_assignments_persisted",()->{Map<String,Object> c=ctx(skill("протокол"),null);c.put("confirm_writes",true);chat("skill-meeting","Разбери протокол и запиши в БД встречу MATRIX_MEETING: 2026-11-11, участники Тестов и Примерова. Решили начать пилот. Поручения: Тестову подготовить MATRIX_ACTION_A до 2026-11-20; Примеровой проверить MATRIX_ACTION_B до 2026-11-21. Запиши оба поручения отдельными задачами и свяжи с этой встречей. Запись подтверждена. Открытый вопрос: кто утвердит MATRIX_QUESTION?",c);check(scalarText(projectPath,"SELECT COUNT(*) FROM tasks WHERE title LIKE '%MATRIX_ACTION_%' AND linked_meeting IN(SELECT id FROM meetings WHERE title LIKE '%MATRIX_MEETING%')").equals("2"),"meeting skill lost assignment or link");check(scalarText(projectPath,"SELECT summary FROM meetings WHERE title LIKE '%MATRIX_MEETING%'").contains("MATRIX_QUESTION"),"open meeting question was lost");});
        run("skill_status_uses_actual_database",()->{String text=response(chat("skill-status","Подготовь статус проекта по структуре активного навыка: сделано, в работе, риски и блокеры, план следующего периода, общий статус. Ничего не придумывай.",ctx(skill("статусом"),null)));check(text.contains("MATRIX_TASK_OPEN")&&text.contains("MATRIX_RISK_DELAY")&&text.toLowerCase().contains("общий статус"),"status skill lost sections or source facts");});
        run("skill_steering_committee_preparation",()->{String text=response(chat("skill-uk","Подготовь сводку к УК: статус, сроки, бюджет, достижения, риски и запросы на решения. Сначала проверь фактические данные БД, отсутствующие не выдумывай.",ctx(skill("подготовка"),null)));check(text.contains("MATRIX_PROJECT_ALPHA")&&text.contains("MATRIX_RISK_DELAY")&&text.toLowerCase().contains("бюджет"),"steering committee skill ignored project facts");});
        // Keep private corporate URLs out of real-provider fixtures, retaining the skill algorithm.
        String confluence=skill("confluence");Map<String,Object> definition=Json.asMap(store.getSkills().get(confluence));definition.put("code",Json.str(definition,"code","").replaceAll("https?://[^\\s]+","https://example.invalid/synthetic"));
        run("skill_confluence_presence_from_synthetic_export",()->{String text=response(chat("skill-confluence","Проверь синтетическую выгрузку страницы проекта MATRIX_CONFLUENCE: бренд Супер Лента; Блок 1 заполнен; Блок 2 отсутствует; Блок 3 есть; паспорт проекта отсутствует. Нет доступа к сети и отправке сообщений. Дай результат проверки наличия и недостающие пункты, не утверждай что что-либо отправлено.",obj("skills",List.of(confluence))));check(text.toLowerCase().contains("паспорт")&&text.contains("Нет")&&text.contains("2"),"Confluence skill missed missing blocks");});
        run("skill_confluence_stale_export",()->{String text=response(chat("skill-confluence-stale","Проверь синтетическую выгрузку страницы проекта MATRIX_CONFLUENCE_CURRENT: все три блока и паспорт есть, ссылки есть. План, реестр рисков и статус обновлены 2010-01-01. Проверка на дату 2026-11-11, рабочая фаза. Нет доступа к сети; проверь актуальность по активному навыку.",obj("skills",List.of(confluence))));check(text.toLowerCase().contains("план")&&text.toLowerCase().contains("рисков")&&text.contains("Нет"),"Confluence staleness rules ignored");});
        for(String kind:List.of("паспорт","реестр рисков"))run("tool_excel_"+(kind.equals("паспорт")?"passport":"risks")+"_without_format_hint",()->{String selected=tool(kind.equals("паспорт")?"паспорта":"реестра");Map<String,Object> r=chat("tool-"+(kind.equals("паспорт")?"passport":"risk"),"Подготовь "+kind+" проекта по фактическим данным. Не выдумывай отсутствующие сведения.",ctx(null,selected));Path file=Paths.get(Json.str(r,"file_path",""));check(Files.isRegularFile(file),"selected Excel tool only returned advice");excelTemplate(file,creator.getCorporateExcelTemplate(kind.equals("паспорт")?"паспорт":"риск"));try(var workbook=new XSSFWorkbook(Files.newInputStream(file))){if(kind.equals("\u043f\u0430\u0441\u043f\u043e\u0440\u0442")){check(workbook.getSheetAt(0).getRow(0).getCell(0).getStringCellValue().contains("MATRIX_PROJECT_ALPHA"),"passport form was not filled");check(workbook.getSheetIndex("\u041f\u0440\u0438\u043c\u0435\u0440_\u041f\u0430\u0441\u043f\u043e\u0440\u0442")<0,"passport example sheet leaked into output");}else check(workbook.getSheetAt(0).getRow(18).getCell(7).getStringCellValue().contains("MATRIX_RISK_DELAY"),"risk data placed outside template table");}check(Json.arr(r,"usage").toString().contains(selected),"generator usage not recorded");});
        for(String kind:List.of("status","committee"))run("tool_ppt_"+kind+"_without_format_hint",()->{String selected=tool(kind.equals("status")?"статуса":"шаблоне"),request=kind.equals("status")?"Подготовь статус проекта по данным БД":"Подготовь материалы к УК по данным проекта";Map<String,Object> r=chat("tool-ppt-"+kind,request,ctx(null,selected));Path file=Paths.get(Json.str(r,"file_path",""));check(Files.isRegularFile(file),"selected PPT tool only returned advice");pptTheme(file,creator.getPresentationTemplate(request,"- "+selected));});
        for(String brand:List.of("Гипер Лента","Группа Лента","Супер Лента"))run("explicit_template_"+(brand.startsWith("Гипер")?"hyper":brand.startsWith("Группа")?"group":"super"),()->{String request="Создай презентацию по шаблону "+brand+" о синтетическом проекте MATRIX_TEMPLATE_CHECK, пять слайдов.";Map<String,Object> r=chat("brand-"+(brand.startsWith("Гипер")?"hyper":brand.startsWith("Группа")?"group":"super"),request,null);pptTheme(Paths.get(Json.str(r,"file_path","")),creator.getPresentationTemplate(request,null));});
        run("automatic_excel_template_without_selected_tool",()->{Map<String,Object> r=chat("auto-risk-template","Создай Excel реестр рисков. Данные CSV: title;impact\nMATRIX_AUTO_RISK;high",null);Path file=Paths.get(Json.str(r,"file_path",""));excelTemplate(file,creator.getCorporateExcelTemplate("риск"));try(var book=new XSSFWorkbook(Files.newInputStream(file))){check(book.getSheetAt(0).getRow(18).getCell(7).getStringCellValue().equals("MATRIX_AUTO_RISK"),"literal risk data not in template table");}});
        run("missing_template_fails_before_model_call",()->{Path missing=out.resolve("missing-template");Files.createDirectories(missing);Agent isolated=new Agent(config,store,manager,new FileCreator(missing.resolve("output").toString(),missing.toString()));long before=TokenBudget.tokensToday();Agent.TaskResult r=isolated.processTask("Создай презентацию по корпоративному шаблону",new ArrayList<>(),null,null,null,null,null,null,false);check(r.response.contains("Не найден")&&r.filePath==null&&TokenBudget.tokensToday()==before,"missing template silently fell back");});
        run("create_database_from_two_excel_sheets",()->{byte[] bytes;try(var workbook=new XSSFWorkbook();var output=new java.io.ByteArrayOutputStream()){var first=workbook.createSheet("matrix_main");String[][] values={{"id","name","amount"},{"1","Alpha","17"},{"2","Beta","23"},{"3","Gamma","31"}};for(int i=0;i<values.length;i++)for(int j=0;j<values[i].length;j++){var row=first.getRow(i);if(row==null)row=first.createRow(i);row.createCell(j).setCellValue(values[i][j]);}var second=workbook.createSheet("matrix_extra");second.createRow(0).createCell(0).setCellValue("label");second.createRow(1).createCell(0).setCellValue("SECOND_SHEET_FACT");workbook.write(output);bytes=output.toByteArray();}Map<String,Object> uploaded=upload("db-multisheet","matrix-source.xlsx",bytes);check(Json.str(uploaded,"text","").contains("SECOND_SHEET_FACT"),"second uploaded sheet missing");chat("db-multisheet","Создай базу данных xlsx_matrix из обоих листов приложенного Excel. Таблица matrix_main: id,name,amount, все 3 строки. Таблица matrix_extra: label, одна строка SECOND_SHEET_FACT. Не теряй данные второго листа.",obj("attachment_ids",List.of(Json.str(uploaded,"id",""))));String path=Json.str(store.getDatabase("xlsx_matrix"),"path","");check(scalarText(path,"SELECT SUM(amount) FROM matrix_main").equals("71")&&scalarText(path,"SELECT label FROM matrix_extra").equals("SECOND_SHEET_FACT"),"database lost workbook data");});
        store.saveAll();
    }
}
